arguments.command:
cd /tmp/vally-eval-trial-bkdQnX && mkdir -p tests/CheckoutPricing.UnitTests/Checkout && cat > src/CheckoutPricing.Application/CalculatePayableTotal.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Gold }

public sealed class CalculatePayableTotalHandler
{
    public decimal Handle(CustomerTier tier, decimal orderSubtotal) => 0m;
}
E
cat > tests/CheckoutPricing.UnitTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void S1_GoldCustomerReceivesTheApprovedDiscount()
    {
        var payableTotal = new CalculatePayableTotalHandler().Handle(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, payableTotal);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests --filter "FullyQualifiedName~LoyaltyDiscountTests" --verbosity quiet 2>&1 | tail -20

